"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6346],{16346:a=>{a.exports=JSON.parse('{"slug":"klyuchevaya-stavka-23-oktyabrya-2026-pauza","locale":"ru","title":"25 из 26 экономистов ждут, что Банк России 23 октября сохранит ставку 14%","description":"Почти все экономисты ждут, что 23 октября 2026 года Банк России сохранит ставку 14%. Почему пауза и что она значит для вкладов и кредитов.","blocks":[{"id":"b001","kind":"paragraph","text":"23 октября 2026 года совет директоров Банка России объявит решение по ключевой ставке и обновит макропрогноз. В опросе 26 экономистов 25 ждут сохранения ставки 14%, один ждёт снижения до 13,75%. Первый зампред правления Сбербанка Александр Ведяхин тоже называет сохранение самым вероятным вариантом. С 6 июня 2025 года ставку снижали с 21% до 14% в июле 2026-го, а 11 сентября впервые сделали паузу. Часть экономистов допускает, что она продлится до конца года. Последнее заседание 2026 года назначено на 18 декабря."},{"id":"b002","kind":"paragraph","text":"Паузу объясняют цены. С 1 января по 12 октября они выросли на 6,1%, годовая инфляция, по оценке Минэкономразвития, 7,22%, а прогноз регулятора на 2026 год 6–7%. Председатель Банка России Эльвира Набиуллина 11 сентября объяснила, что снижение остановили разовые факторы, на которые ставка не влияет. Регулятор называл среди них перебои в производстве и дорогое топливо. Но устойчивую инфляцию, без разовых скачков, регулятор тогда же оценил в 5–6% в пересчёте на год, выше цели в 4%."},{"id":"b003","kind":"paragraph","text":"Почему разовый скачок может стать постоянным, видно по ожиданиям. Представим парикмахера, который ждёт, что аренда и краска за год подорожают на 14%. Он поднимает цену стрижки уже сейчас. Клиент, который тоже ждёт подорожания, покупает телевизор сегодня, пока не подорожал, и берёт кредит. Цены растут, потому что их роста ждут. Это называют инфляционными ожиданиями. В сентябре население ждало инфляцию на год вперёд 14,2%, в августе 13,7%, и это почти вдвое выше фактических 7,22%."},{"id":"b004","kind":"paragraph","text":"Ещё одно условие Банк России назвал сам: снижение ставки в 2027 году зависит от того, сократится ли дефицит бюджета. Когда государство тратит больше, чем получает, в экономику приходит дополнительный спрос, и цены растут быстрее."},{"id":"b005","kind":"paragraph","text":"Для вкладчиков пауза означает, что ставки по вкладам держатся. Средняя максимальная ставка в 10 крупнейших банках в конце сентября была 13,05%. Для заёмщиков кредиты и рыночная ипотека остаются дорогими. Если 23 октября ставку сохранят, следующий шанс на снижение будет только 18 декабря."},{"id":"b006","kind":"paragraph","text":"Вкладчик, который сейчас открывает вклад на год, закрепляет около 13%. Если снижение ставки начнётся раньше, чем ждут экономисты, он выиграет. Если ставку придётся повысить, он упустит более высокие проценты. Заёмщику ожидание дешёвого кредита обойдётся как минимум в 2 месяца, а цены за это время продолжат расти. Новый макропрогноз 23 октября покажет, как долго Банк России собирается держать ставку."},{"id":"b007","kind":"heading","text":"Какое решение по ключевой ставке ждут 23 октября 2026 года?"},{"id":"b008","kind":"paragraph","text":"Почти все экономисты ждут сохранения ставки 14%. В опросе 26 экономистов так ответили 25, один ждёт снижения до 13,75%. Сбербанк тоже считает сохранение самым вероятным вариантом."},{"id":"b009","kind":"heading","text":"Почему Банк России не снижает ставку?"},{"id":"b010","kind":"paragraph","text":"С начала года цены выросли на 6,1%, почти до верхней границы прогноза Банка России 6–7%. Скачок частично разовый: дорогое топливо и перебои в производстве. Но население ждёт инфляцию 14,2% на год вперёд, и регулятор опасается, что разовое ускорение перейдёт в устойчивое."},{"id":"b011","kind":"heading","text":"Что пауза в снижении ставки значит для вкладов и ипотеки?"},{"id":"b012","kind":"paragraph","text":"Пока ставка 14%, вклады остаются доходными, средняя максимальная ставка в крупнейших банках в конце сентября была 13,05%. Кредиты и рыночная ипотека остаются дорогими. Следующее решение после 23 октября Банк России примет 18 декабря."}],"sources":[{"label":"Консенсус-прогноз \xabВедомостей\xbb — экономисты почти единогласно ждут паузы в решении ЦБ по ставке","url":"https://www.vedomosti.ru/economics/articles/2026/10/16/1237503-konsensus-prognoz-vedomostei"},{"label":"Сбербанк ожидает сохранения ключевой ставки","url":"https://www.kommersant.ru/doc/9026103"},{"label":"Сбер ждет сохранения ставки ЦБ по итогам октябрьского заседания","url":"https://www.interfax.ru/business/1122297"},{"label":"Инфляционные ожидания и потребительские настроения, сентябрь 2026","url":"https://www.cbr.ru/analytics/dkp/inflationary_expectations/Infl_exp_26-09/"},{"label":"Инфляция в России с 6 по 12 октября составила 0,11%","url":"https://www.interfax.ru/business/1122459"},{"label":"Банк России опубликовал график заседаний по ключевой ставке на 2026 год","url":"https://finance.mail.ru/article/bank-rossii-opublikoval-grafik-zasedaniy-po-klyuchevoy-stavke-na-2026-god-68067122/"},{"label":"Средняя максимальная ставка по вкладам десяти банков выросла до 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"Банк России снизил ключевую ставку до 20% годовых","url":"https://finance.mail.ru/article/bank-rossii-snizil-klyuchevuyu-stavku-do-20-godovyh-66466367/"},{"label":"Банк России повысил прогноз по инфляции на 2026 год","url":"https://www.kommersant.ru/doc/8843971"}],"sourceBodySha256":"fe62eaf826a4de568479af2c8bab712a15f8ab8a8d9f9a89aca0a2ed2e59bfc4"}')}}]);